.switch {
  /* Switch-local dimensions (atom-private knobs).
   *
   * `--switch-thumb-size`, NOT `--switch-thumb`: the semantic layer already owns
   * `--switch-thumb` and it is the thumb's COLOUR. Declaring a length under that
   * name here shadowed the token inside this rule, so `background:
   * var(--switch-thumb)` resolved to `1rem`, which is not a colour — the
   * declaration was dropped and the thumb was drawn with no fill at all. The
   * switch rendered as a bare blue track with nothing on it, and neither tsc,
   * the linters nor the axe sweep can see an invalid CSS value (owner,
   * 2026-08-29). */
  --switch-width: 2.25rem;
  --switch-height: 1.25rem;
  --switch-thumb-size: 1rem;
  position: relative;
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
  width: var(--switch-width);
  height: var(--switch-height);
  border-radius: var(--radius-full);
  background: var(--switch-track-off);
  transition: background var(--duration-fast);
}
/* The track is 20px tall because that is the shape; the TARGET has to be 24
 * (SC 2.5.8). A pseudo-element extends the hit area without moving a pixel of
 * the drawing — ::after is already the thumb. */
.switch::before {
  content: "";
  position: absolute;
  inset-block: calc((var(--space-6) - var(--switch-height)) / -2);
  inset-inline: 0;
}
.switch[aria-checked="true"] { background: var(--primary); }
.switch[disabled] { opacity: var(--disabled-opacity); cursor: not-allowed; }
/* The same three answers the rest of the system gives. A switch that does not
 * acknowledge the pointer reads as a picture of a switch. */
.switch:hover:not([disabled]) { background: var(--accent-strong); }
.switch[aria-checked="true"]:hover:not([disabled]) { background: var(--primary-hover); }
.switch:active:not([disabled]) { background: var(--accent-active); }
.switch[aria-checked="true"]:active:not([disabled]) { background: var(--primary-active); }
/* Marked wrong: the track carries the red, since the thumb is the value. */
.switch[aria-invalid="true"] { box-shadow: inset 0 0 0 2px var(--destructive); }
.switch[aria-invalid="true"]:focus-visible { outline-color: var(--destructive); }

.switch::after {
  content: "";
  position: absolute;
  inset-inline-start: var(--space-2xs);
  width: var(--switch-thumb-size);
  height: var(--switch-thumb-size);
  border-radius: var(--radius-full);
  background: var(--switch-thumb);
  box-shadow: var(--shadow-sm);
  transition: inset-inline-start var(--duration-fast);
}
.switch[aria-checked="true"]::after { inset-inline-start: calc(100% - var(--switch-thumb-size) - var(--space-2xs)); }

import './Switch.css'
import type { ButtonHTMLAttributes } from 'react'
import { cn } from '../lib/cn'

type Props = Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children' | 'onChange'> & {
  /** Controlled: the switch draws what it is told and never its own state, so a flip that the
   *  save rejects must not stay flipped.
   */
  checked: boolean
  /** Called with the NEXT value. It is where the save goes; the switch does not move until
   *  `checked` comes back changed.
   */
  onChange: (next: boolean) => void
  label: string
  /** The form rejected this setting. Red track and a red focus ring; the
   *  message belongs to the `<Field>` around it. */
  invalid?: boolean
}

/**
 * An on/off setting that applies the moment it is flipped (role="switch"). A
 * checkbox is for something that applies when a form is submitted.
 *
 * Copy: the label names the state when ON, and never repeats the word "on":
 * "Weekly digest", not "Weekly digest on/off".
 */
export function Switch({ checked, onChange, label, invalid, className, ...rest }: Props) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      aria-invalid={invalid || undefined}
      aria-label={label}
      className={cn('switch', className)}
      onClick={() => onChange(!checked)}
      {...rest}
    />
  )
}
